css:
.rewardreset-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2233;
    background: linear-gradient(165deg, #f4f5fb 0%, #eef0f8 55%, #e9ecf6 100%);
    border-radius: 18px;
}

.rewardreset-container * {
    box-sizing: border-box;
}

.rewardreset-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1a1d3a 0%, #2c2f6b 52%, #3a3f8f 100%);
    color: #f4f3ff;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(26, 29, 58, 0.32);
}

.rewardreset-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.rewardreset-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f3c969;
    background: rgba(243, 201, 105, 0.12);
    border: 1px solid rgba(243, 201, 105, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.rewardreset-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfd0ee;
}

.rewardreset-firmbar {
    display: flex;
    gap: 12px;
    margin-bottom: 18px;
}

.rewardreset-firm-item {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 12px 16px;
    box-shadow: 0 4px 14px rgba(28, 34, 51, 0.07);
    border-left: 5px solid #3a3f8f;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.rewardreset-firm-item:nth-child(2) { border-left-color: #b9842b; }
.rewardreset-firm-item:nth-child(3) { border-left-color: #2f8f6f; }

.rewardreset-firm-k {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7d839b;
}

.rewardreset-firm-v {
    font-size: 0.9rem;
    font-weight: 700;
    color: #2c2f6b;
    line-height: 1.35;
}

.rewardreset-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #444a66;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.rewardreset-period-counter #currentDay,
.rewardreset-period-counter #maxPeriods {
    font-weight: 800;
    color: #3a3f8f;
}

.rewardreset-round-name {
    background: rgba(58, 63, 143, 0.13);
    color: #2c2f6b;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.rewardreset-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a6c14;
    background: rgba(243, 201, 105, 0.20);
    border: 1px solid rgba(185, 132, 43, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.rewardreset-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.rewardreset-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(28, 34, 51, 0.08);
    border-top: 4px solid #3a3f8f;
}

.rewardreset-card-engagement { border-top-color: #3a3f8f; }
.rewardreset-card-turnover { border-top-color: #c0573f; }
.rewardreset-card-equity { border-top-color: #b9842b; }
.rewardreset-card-fit { border-top-color: #2f8f6f; }

.rewardreset-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6e7390;
}

.rewardreset-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1c2233;
    font-variant-numeric: tabular-nums;
}

.rewardreset-card-engagement .rewardreset-value { color: #3a3f8f; }
.rewardreset-card-turnover .rewardreset-value { color: #c0573f; }
.rewardreset-card-equity .rewardreset-value { color: #b9842b; }
.rewardreset-card-fit .rewardreset-value { color: #2f8f6f; }

.rewardreset-sublabel {
    font-size: 0.74rem;
    color: #828aa3;
    line-height: 1.35;
}

/* Performance-driven state colours on the headline KPIs. */
.rewardreset-card-engagement.rewardreset-good .rewardreset-value { color: #2f8f6f; }
.rewardreset-card-engagement.rewardreset-good { border-top-color: #2f8f6f; }
.rewardreset-card-turnover.rewardreset-good .rewardreset-value { color: #2f8f6f; }
.rewardreset-card-turnover.rewardreset-good { border-top-color: #2f8f6f; }
.rewardreset-card-turnover.rewardreset-bad .rewardreset-value { color: #c0573f; }
.rewardreset-card-equity.rewardreset-good .rewardreset-value { color: #2f8f6f; }
.rewardreset-card-equity.rewardreset-good { border-top-color: #2f8f6f; }
.rewardreset-card-equity.rewardreset-bad .rewardreset-value { color: #c0573f; }

.rewardreset-envelope-bar {
    background: #ffffff;
    border: 1px solid #e2e4f0;
    border-radius: 12px;
    padding: 12px 16px 14px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(28, 34, 51, 0.06);
}

.rewardreset-envelope-head {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 9px;
    font-weight: 700;
    font-size: 0.9rem;
    color: #444a66;
}

.rewardreset-envelope-head #envelopeStatusDisplay {
    font-size: 1.02rem;
    font-weight: 800;
    color: #2f8f6f;
    font-variant-numeric: tabular-nums;
}

.rewardreset-envelope-bar.rewardreset-over #envelopeStatusDisplay { color: #c0573f; }

.rewardreset-envelope-track {
    display: flex;
    width: 100%;
    height: 30px;
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid #e2e4f0;
}

.rewardreset-envelope-seg {
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.68rem;
    font-weight: 700;
    color: #ffffff;
    overflow: hidden;
    white-space: nowrap;
    transition: width 0.4s ease;
}

.rewardreset-seg-base { background: #3a3f8f; }
.rewardreset-seg-variable { background: #b9842b; }
.rewardreset-seg-dev { background: #2f8f6f; }
.rewardreset-seg-benefits { background: #8a90ad; }

.rewardreset-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #3a3f8f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 34, 51, 0.07);
}

.rewardreset-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.rewardreset-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2c2f6b;
    margin-bottom: 6px;
}

.rewardreset-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4159;
}

.rewardreset-briefing-text strong { color: #3a3f8f; }
.rewardreset-briefing-text em { color: #b9842b; font-style: italic; }

.rewardreset-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 34, 51, 0.07);
}

.rewardreset-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2c2f6b;
    border-bottom: 2px solid #e9eaf3;
    padding-bottom: 8px;
}

.rewardreset-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3147;
    margin: 14px 0 6px;
}

.rewardreset-container select,
.rewardreset-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c9cce0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1c2233;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.rewardreset-container select:focus,
.rewardreset-container input[type="number"]:focus {
    outline: none;
    border-color: #3a3f8f;
    box-shadow: 0 0 0 3px rgba(58, 63, 143, 0.16);
}

.rewardreset-container select option {
    background-color: #ffffff;
    color: #1c2233;
}

.rewardreset-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b9842b;
}

.rewardreset-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #444a66;
    margin-top: 4px;
}

.rewardreset-range-readout span:nth-child(2) {
    color: #9a6c14;
    font-weight: 800;
}

.rewardreset-hint {
    font-size: 0.8rem;
    color: #828aa3;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.rewardreset-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.rewardreset-container .btn-primary {
    background: linear-gradient(135deg, #2c2f6b 0%, #3a3f8f 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(44, 47, 107, 0.32);
}

.rewardreset-container .btn-primary:hover {
    filter: brightness(1.10);
}

.rewardreset-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c9cce0;
    color: #5d6486;
    background: transparent;
}

.rewardreset-coach {
    background: linear-gradient(160deg, #1a1d3a 0%, #25285a 100%);
    color: #e6e6fb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(26, 29, 58, 0.26);
}

.rewardreset-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f3c969;
    margin-bottom: 8px;
}

.rewardreset-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.rewardreset-coach-body strong { color: #9fb8ff; }
.rewardreset-coach-body em { color: #f3c969; font-style: italic; }

.rewardreset-history,
.rewardreset-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 34, 51, 0.07);
}

.rewardreset-history h3,
.rewardreset-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2c2f6b;
}

.rewardreset-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4159;
}

.rewardreset-container table#usfHistoryTable th {
    background: #eeeff8;
    color: #3a3f8f;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #dadcec;
}

.rewardreset-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef0f5;
    color: #3a4159;
}

.rewardreset-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f8fc;
}

.rewardreset-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .rewardreset-container {
        padding: 14px;
    }
    .rewardreset-header h1 {
        font-size: 1.7rem;
    }
    .rewardreset-firmbar {
        flex-direction: column;
    }
    .rewardreset-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .rewardreset-value {
        font-size: 2rem;
    }
    .rewardreset-clock {
        margin-left: 0;
    }
    .rewardreset-period-counter {
        font-size: 0.88rem;
    }
    .rewardreset-envelope-head {
        flex-direction: column;
        align-items: flex-start;
        gap: 4px;
    }
    .rewardreset-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.rr-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.rr-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #7f8398; margin-bottom: 6px; }
.rr-cm-verdict { font-size: 22px; font-weight: 700; color: #eceef6; margin-bottom: 8px; }
.rr-cm-score { font-size: 16px; color: #eceef6; margin-bottom: 16px; }
.rr-cm-score strong { color: #e0a63c; }
.rr-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #7f8398; margin-bottom: 8px; }
.rr-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.rr-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.rr-cm-target.rr-cm-met { background: rgba(224,166,60,0.16); color: #f0c67e; border-color: rgba(224,166,60,0.4); }
.rr-cm-target.rr-cm-missed { background: rgba(255,110,110,0.14); color: #ff9d9d; border-color: rgba(255,110,110,0.36); }
.rr-cm-tick { font-weight: 700; }
.rr-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.rr-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,130,170,0.12); border-radius: 8px; min-width: 92px; }
.rr-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #7f8398; }
.rr-cm-metric strong { font-size: 16px; color: #eceef6; }
.rr-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.rr-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(224,166,60,0.10); border-left: 3px solid #e0a63c; border-radius: 4px; color: #e3e6f0; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .rr-cm-metric { min-width: 70px; } .rr-cm-verdict { font-size: 19px; } }

