(function() {
    'use strict';

    class RewardResetAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Reward Reset`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card — Logika Solutions d.o.o.
            this.ENVELOPE = 49.5;            // EUR M frozen compensation envelope
            this.START_ENGAGEMENT = 58;      // /100, benchmark ~72
            this.BENCHMARK_ENGAGEMENT = 72;
            this.START_TURNOVER = 21;        // % voluntary mid-level engineer turnover
            this.START_GAP = 11;             // % unexplained gender pay gap
            this.START_FIT = 30;             // strategy-fit index (0–100)
            this.EXIT_COST = 38;             // EUR k per regretted exit
            this.PEER_VARIABLE_MIN = 18;     // peer variable share floor (%)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    engagement: this.START_ENGAGEMENT,   // /100
                    turnover: this.START_TURNOVER,       // %
                    gap: this.START_GAP,                 // % pay-equity gap
                    fit: this.START_FIT,                 // strategy-fit index 0–100
                    variableShare: 8,                    // % of envelope that is variable
                    devSpend: 0,                         // EUR M redirected to development
                    overBudget: false,                  // breached the frozen envelope
                    raisedBaseAcross: false,             // across-the-board raise error
                    metricMisaligned: false,             // metrics contradict strategy
                    perverseLive: false,                 // perverse individual-incentive side-effect
                    equityUnfixed: true,                 // 11% gap not yet corrected
                    noChangeMgmt: false,                 // changed pay with no transition/council
                    engagementHistory: [this.START_ENGAGEMENT],
                    turnoverHistory: [this.START_TURNOVER],
                    gapHistory: [this.START_GAP],
                    fitHistory: [this.START_FIT],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the concept's COMMON ERRORS so a
                // blind click-through must NOT auto-win.
                state.decisions = {
                    root: `underpaid`,
                    cost: `ignore`,
                    equityPriority: `later`,
                    depth: 35,
                    variable: 8,
                    metric: `billable`,
                    dev: 0,
                    base: `acrosstheboard`,
                    equityFix: `grandfather`,
                    behaviour: `ignore`,
                    comms: `leak`,
                    council: 30,
                    pitch: `cost`,
                    philosophy: `pay`,
                    probe: `dodge`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ro = document.getElementById(`rootInput`);
                const co = document.getElementById(`costInput`);
                const eq = document.getElementById(`equityPriorityInput`);
                const de = document.getElementById(`depthInput`);
                if (ro) decisions.root = ro.value;
                if (co) decisions.cost = co.value;
                if (eq) decisions.equityPriority = eq.value;
                if (de) decisions.depth = parseInt(de.value, 10);
                if (!Number.isFinite(decisions.depth) || decisions.depth < 0 || decisions.depth > 100) {
                    warn(`warn_depth_range`); return false;
                }
            } else if (round === 2) {
                const va = document.getElementById(`variableInput`);
                const me = document.getElementById(`metricInput`);
                const dv = document.getElementById(`devInput`);
                const ba = document.getElementById(`baseInput`);
                if (va) decisions.variable = parseInt(va.value, 10);
                if (me) decisions.metric = me.value;
                if (dv) decisions.dev = parseFloat(dv.value);
                if (ba) decisions.base = ba.value;
                if (!Number.isFinite(decisions.variable) || decisions.variable < 8 || decisions.variable > 30) {
                    warn(`warn_variable_range`); return false;
                }
                if (!Number.isFinite(decisions.dev) || decisions.dev < 0 || decisions.dev > 6) {
                    warn(`warn_dev_range`); return false;
                }
            } else if (round === 3) {
                const ef = document.getElementById(`equityFixInput`);
                const be = document.getElementById(`behaviourInput`);
                const cm = document.getElementById(`commsInput`);
                const cl = document.getElementById(`councilInput`);
                if (ef) decisions.equityFix = ef.value;
                if (be) decisions.behaviour = be.value;
                if (cm) decisions.comms = cm.value;
                if (cl) decisions.council = parseInt(cl.value, 10);
                if (!Number.isFinite(decisions.council) || decisions.council < 0 || decisions.council > 100) {
                    warn(`warn_council_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const ph = document.getElementById(`philosophyInput`);
                const pr = document.getElementById(`probeInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (ph) decisions.philosophy = ph.value;
                if (pr) decisions.probe = pr.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let engDelta = 0, turnDelta = 0, gapDelta = 0, fitDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the reward–strategy gap (Common Error 1 & equity).
                switch (d.root) {
                    case `misaligned`: fitDelta += 8; engDelta += 2; coachKey = `coach_r1_misaligned`; break;
                    case `underpaid`: fitDelta -= 3; coachKey = `coach_r1_underpaid`; break;
                    case `managers`: fitDelta -= 2; coachKey = `coach_r1_managers`; break;
                }

                switch (d.cost) {
                    case `quantify`: fitDelta += 3; engDelta += 1; break;
                    case `ignore`: fitDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r1_costignore`; break;
                    case `hours`: fitDelta -= 3; if (coachKey === `coach_default`) coachKey = `coach_r1_costhours`; break;
                }

                switch (d.equityPriority) {
                    case `precondition`: gapDelta -= 1; engDelta += 2; break;
                    case `later`: engDelta -= 1; break;
                    case `grandfather`: gapDelta += 0.5; engDelta -= 2; coachKey = `coach_r1_grandfather`; break;
                }

                // Diagnostic depth — segmenting the workforce sharpens every later move.
                if (d.depth >= 65) { fitDelta += 4; engDelta += 1; }
                else if (d.depth <= 25) { fitDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r1_shallow` : coachKey; }

                if (d.root === `misaligned` && d.equityPriority === `precondition` && d.cost === `quantify`) {
                    coachKey = `coach_r1_sharp`;
                    summaryKey = `sum_r1_good`;
                } else {
                    summaryKey = `sum_r1_weak`;
                }
            } else if (round === 2) {
                // Redesign the incentive mix and metrics (Common Errors 1, 2, 5; the envelope constraint).
                ds.variableShare = d.variable;
                ds.devSpend = d.dev;

                // (a) The fixed-vs-variable move toward the peer band.
                if (d.variable >= this.PEER_VARIABLE_MIN && d.variable <= 22) {
                    fitDelta += 6; engDelta += 3; // healthy risk-sharing in the peer band
                } else if (d.variable > 22) {
                    fitDelta += 2; engDelta -= 2; turnDelta += 1; // over-loads risk onto staff
                    coachKey = `coach_r2_overvariable`;
                } else if (d.variable >= 12) {
                    fitDelta += 3; engDelta += 1; // partial move
                } else {
                    engDelta -= 1; coachKey = `coach_r2_timid`; // barely moved off 8%
                }

                // (b) Metric set — the core vertical-fit lever (decision tree #2 & #3).
                switch (d.metric) {
                    case `balanced`:
                        fitDelta += 14; engDelta += 5; turnDelta -= 3; ds.metricMisaligned = false;
                        coachKey = `coach_r2_balanced`;
                        break;
                    case `billable`:
                        // Bigger bonus on the exact behaviour the strategy is leaving behind.
                        fitDelta -= 12; engDelta -= 2; ds.metricMisaligned = true;
                        // The larger the variable share on the wrong metric, the worse the misfit.
                        fitDelta -= Math.round((d.variable - 8) * 0.6);
                        coachKey = `coach_r2_billable`;
                        break;
                    case `individual`:
                        fitDelta -= 4; engDelta -= 4; turnDelta += 2; ds.metricMisaligned = true; ds.perverseLive = true;
                        coachKey = `coach_r2_individual`;
                        break;
                }

                // (c) Talent-development line (decision tree #5 — the #1 reason people leave is "no growth path").
                if (d.dev >= 2.5) { engDelta += 6; turnDelta -= 4; fitDelta += 4; }
                else if (d.dev >= 1) { engDelta += 3; turnDelta -= 2; fitDelta += 2; }
                else { turnDelta += 3; engDelta -= 2; if (coachKey === `coach_default` || d.metric === `balanced`) coachKey = `coach_r2_nodev`; }

                // (d) Base-pay funding choice (decision tree #1 — across-the-board raise that breaks the envelope).
                switch (d.base) {
                    case `differentiated`: fitDelta += 5; engDelta += 2; gapDelta -= 1; turnDelta -= 1; break;
                    case `flat`: fitDelta += 2; break;
                    case `acrosstheboard`:
                        ds.raisedBaseAcross = true; ds.overBudget = true;
                        engDelta += 1; fitDelta -= 6; turnDelta += 1;
                        coachKey = `coach_r2_acrosstheboard`;
                        break;
                }

                summaryKey = (d.metric === `balanced` && d.variable >= this.PEER_VARIABLE_MIN && d.variable <= 22 && d.dev >= 2.5 && d.base !== `acrosstheboard`) ? `sum_r2_good` :
                             (d.metric === `billable` ? `sum_r2_billable` :
                             (d.base === `acrosstheboard` ? `sum_r2_raise` :
                             (d.metric === `individual` ? `sum_r2_individual` : `sum_r2_weak`)));
            } else if (round === 3) {
                // Stress-test for equity and behaviour (Common Errors 3, 4, 5).
                // (a) Pay-equity correction (decision tree #4).
                switch (d.equityFix) {
                    case `correct`: gapDelta -= 11; engDelta += 5; fitDelta += 3; ds.equityUnfixed = false; break;
                    case `cosmetic`: gapDelta -= 2; engDelta -= 1; coachKey = `coach_r3_cosmetic`; break;
                    case `grandfather`: gapDelta += 0; engDelta -= 4; ds.equityUnfixed = true; coachKey = `coach_r3_grandfather`; break;
                }

                // (b) Behavioural side-effect fix (decision tree #3 — perverse incentives & horizontal fit).
                switch (d.behaviour) {
                    case `collaboration`:
                        fitDelta += 8; engDelta += 3; ds.perverseLive = false;
                        if (ds.metricMisaligned && d.metric !== undefined) { /* re-weight also helps fit */ }
                        ds.metricMisaligned = false;
                        coachKey = (coachKey === `coach_default`) ? `coach_r3_collaboration` : coachKey;
                        break;
                    case `double`:
                        fitDelta -= 6; engDelta -= 4; turnDelta += 3; ds.perverseLive = true;
                        coachKey = `coach_r3_double`;
                        break;
                    case `ignore`:
                        fitDelta -= 3; engDelta -= 2; if (ds.perverseLive) turnDelta += 2;
                        coachKey = (coachKey === `coach_default`) ? `coach_r3_behaviourignore` : coachKey;
                        break;
                }

                // (c) Change communication & transition (decision tree #6).
                switch (d.comms) {
                    case `transition`: engDelta += 5; turnDelta -= 3; ds.noChangeMgmt = false; break;
                    case `announce`: engDelta -= 2; turnDelta += 1; ds.noChangeMgmt = true; coachKey = (coachKey === `coach_default`) ? `coach_r3_announce` : coachKey; break;
                    case `leak`: engDelta -= 5; turnDelta += 3; ds.noChangeMgmt = true; coachKey = `coach_r3_leak`; break;
                }

                // Works-council voice — procedural fairness lever.
                if (d.council >= 60) { engDelta += 3; turnDelta -= 1; if (d.comms === `transition`) coachKey = `coach_r3_fair`; }
                else if (d.council <= 25) { engDelta -= 2; turnDelta += 1; }

                summaryKey = (d.equityFix === `correct` && d.behaviour === `collaboration` && d.comms === `transition`) ? `sum_r3_good` :
                             (d.equityFix !== `correct` ? `sum_r3_equity` :
                             (d.behaviour !== `collaboration` ? `sum_r3_behaviour` : `sum_r3_weak`));
            } else if (round === 4) {
                // Project the outcomes and defend the reset (decision tree #1; debrief).
                switch (d.philosophy) {
                    case `fit`: fitDelta += 7; engDelta += 3; turnDelta -= 2; coachKey = `coach_r4_fit`; break;
                    case `pay`: fitDelta -= 5; engDelta += 1; turnDelta += 1; ds.raisedBaseAcross = true; coachKey = `coach_r4_pay`; break;
                    case `control`: engDelta -= 4; turnDelta += 2; fitDelta -= 3; coachKey = `coach_r4_control`; break;
                }

                switch (d.pitch) {
                    case `system`: fitDelta += 4; engDelta += 2; break;
                    case `cost`: fitDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_cost` : coachKey; break;
                    case `onekpi`: engDelta -= 2; fitDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_onekpi` : coachKey; break;
                }

                switch (d.probe) {
                    case `own`: fitDelta += 4; engDelta += 3; if (d.philosophy === `fit`) coachKey = `coach_r4_own`; break;
                    case `dodge`: engDelta -= 2; fitDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_dodge` : coachKey; break;
                    case `blame`: engDelta -= 4; fitDelta -= 4; coachKey = `coach_r4_blame`; break;
                }

                if (d.conviction >= 60) { fitDelta += 2; engDelta += 1; }
                else if (d.conviction <= 25) { fitDelta -= 2; }

                summaryKey = (d.philosophy === `fit` && d.pitch === `system` && d.probe === `own`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.engagement = Math.max(0, Math.min(100, Math.round((ds.engagement + engDelta) * 10) / 10));
            ds.gap = Math.max(0, Math.min(30, Math.round((ds.gap + gapDelta) * 10) / 10));
            ds.fit = Math.max(0, Math.min(100, Math.round(ds.fit + fitDelta)));

            // ---- Turnover is DERIVED: it falls when engagement is high, the system
            // fits the strategy, pay is equitable and growth paths are funded; it rises
            // when those break. Direct deltas above nudge it; the model floors/ceilings it. ----
            const engFactor = (ds.engagement - this.START_ENGAGEMENT) / (this.BENCHMARK_ENGAGEMENT - this.START_ENGAGEMENT); // ~ -? .. >1
            const fitFactor = (ds.fit - this.START_FIT) / (100 - this.START_FIT); // 0..1 above start
            const equityPenalty = ds.gap / 100; // unresolved gap keeps people leaving
            let derivedTurnover = this.START_TURNOVER
                - 7.0 * Math.max(-0.5, Math.min(1.2, engFactor))
                - 4.0 * Math.max(0, Math.min(1, fitFactor))
                + 12.0 * equityPenalty;
            // Blend the direct nudges with the derived model so single moves still register.
            ds.turnover = Math.max(4, Math.min(30, Math.round((ds.turnover + turnDelta) * 0.45 + derivedTurnover * 0.55) * 10) / 10);

            // Across-the-board raise breaks the frozen envelope — a hard fail flag.
            if (ds.raisedBaseAcross) ds.overBudget = true;

            ds.engagementHistory.push(ds.engagement);
            ds.turnoverHistory.push(ds.turnover);
            ds.gapHistory.push(ds.gap);
            ds.fitHistory.push(ds.fit);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            this._updateEnvelopeBar(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                engagement: ds.engagement,
                engDelta: Math.round(engDelta * 10) / 10,
                turnover: ds.turnover,
                turnDelta: Math.round(turnDelta * 10) / 10,
                gap: ds.gap,
                gapDelta: Math.round(gapDelta * 10) / 10,
                fit: ds.fit,
                fitDelta: Math.round(fitDelta),
                variableShare: ds.variableShare,
                devSpend: ds.devSpend,
                overBudget: ds.overBudget,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _updateEnvelopeBar(ds) {
            // Visualise the re-mix: variable + development carved from base, benefits steady.
            const benefits = 12;
            const variable = Math.max(0, ds.variableShare);
            // devSpend is EUR M out of 49.5 -> percentage points.
            const devPct = Math.max(0, Math.round((ds.devSpend / this.ENVELOPE) * 1000) / 10);
            let base = 100 - benefits - variable - devPct;
            const over = ds.overBudget || base < 0;
            if (base < 0) base = 0;

            const set = (id, pct) => {
                const el = document.getElementById(id);
                if (el) el.style.width = Math.max(0, pct) + `%`;
            };
            set(`segBase`, base);
            set(`segVariable`, variable);
            set(`segDev`, devPct);
            set(`segBenefits`, benefits);

            const bar = document.querySelector(`.rewardreset-envelope-bar`);
            const status = document.getElementById(`envelopeStatusDisplay`);
            if (bar) bar.classList.toggle(`rewardreset-over`, !!over);
            if (status) {
                const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
                if (over) {
                    status.textContent = t(`envelope_over`);
                } else {
                    status.textContent = `€${this.ENVELOPE.toFixed(1)}M / €${this.ENVELOPE.toFixed(1)}M`;
                }
            }
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`engagementDisplay`, `domainState.engagement`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.rewardreset-card-engagement`);
                if (card) card.classList.toggle(`rewardreset-good`, n >= self.BENCHMARK_ENGAGEMENT);
                return `${n}`;
            });

            uiManager.bind(`turnoverDisplay`, `domainState.turnover`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.rewardreset-card-turnover`);
                if (card) {
                    card.classList.toggle(`rewardreset-good`, n <= 12);
                    card.classList.toggle(`rewardreset-bad`, n >= 20);
                }
                return `${self._fmt1(n)}%`;
            });

            uiManager.bind(`equityDisplay`, `domainState.gap`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.rewardreset-card-equity`);
                if (card) {
                    card.classList.toggle(`rewardreset-good`, n <= 2);
                    card.classList.toggle(`rewardreset-bad`, n >= 8);
                }
                return `${self._fmt1(n)}%`;
            });

            uiManager.bind(`fitDisplay`, `domainState.fit`, (v) => `${Math.round(Number(v))}`);

            // Slider readouts.
            const wire = (inputId, readoutId, fmt) => {
                const inp = document.getElementById(inputId);
                const out = document.getElementById(readoutId);
                if (inp && out) {
                    const apply = () => { out.textContent = fmt ? fmt(inp.value) : inp.value; };
                    apply();
                    inp.addEventListener(`input`, apply);
                }
            };
            wire(`depthInput`, `depthReadout`);
            wire(`variableInput`, `variableReadout`);
            wire(`devInput`, `devReadout`, (v) => Number(v).toFixed(1));
            wire(`councilInput`, `councilReadout`);

            this._updateEnvelopeBar(window.mySimulation.state.domainState);
        }

        _fmt1(v) {
            // Locale-aware one-decimal: en "5.2", es "5,2".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(v * 10) / 10).toFixed(1);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        getChartConfig() {
            return {
                rewardChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Engagement score (/100)`,
                                data: [],
                                borderColor: `#3a3f8f`,
                                backgroundColor: `rgba(58,63,143,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#3a3f8f`,
                                yAxisID: `y`
                            },
                            {
                                label: `Strategy-fit index (0–100)`,
                                data: [],
                                borderColor: `#2f8f6f`,
                                backgroundColor: `rgba(47,143,111,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f8f6f`,
                                yAxisID: `y`
                            },
                            {
                                label: `Voluntary turnover (%)`,
                                data: [],
                                borderColor: `#c0573f`,
                                backgroundColor: `rgba(192,87,63,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c0573f`,
                                yAxisID: `y`
                            },
                            {
                                label: `Pay-equity gap (%)`,
                                data: [],
                                borderColor: `#b9842b`,
                                backgroundColor: `rgba(185,132,43,0.08)`,
                                borderWidth: 2,
                                borderDash: [2, 3],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b9842b`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#444a66`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#7d839b` }, grid: { color: `rgba(28,34,51,0.06)` },
                                title: { display: true, text: `0–100  /  %`, color: `#7d839b` }
                            },
                            x: {
                                ticks: { color: `#7d839b` }, grid: { color: `rgba(28,34,51,0.04)` },
                                title: { display: true, text: `Round`, color: `#7d839b` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.engagementHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                rewardChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.engagementHistory.map((v) => Math.round(v)) },
                        { data: ds.fitHistory.map((v) => Math.round(v)) },
                        { data: ds.turnoverHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: ds.gapHistory.map((v) => Math.round(v * 10) / 10) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (weights 0.27/0.26/0.22/0.25 + overBudget penalty).
            const engagement = Math.round(ds.engagement);
            const turnover = Math.round(ds.turnover * 10) / 10;
            const gap = Math.round(ds.gap * 10) / 10;
            const fit = Math.round(ds.fit);
            const engScore = Math.max(0, Math.min(100, (engagement / this.BENCHMARK_ENGAGEMENT) * 100));
            const turnScore = Math.max(0, Math.min(100, (this.START_TURNOVER - turnover) / (this.START_TURNOVER - 8) * 100));
            const equityScore = Math.max(0, Math.min(100, (this.START_GAP - gap) / this.START_GAP * 100));
            const fitScore = fit;
            let composite = Math.round(engScore * 0.27 + turnScore * 0.26 + equityScore * 0.22 + fitScore * 0.25);
            if (ds.overBudget) composite = Math.max(0, composite - 25);
            return composite;
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="rr-cm-target ' + (ok ? 'rr-cm-met' : 'rr-cm-missed') + '">'
                    + '<span class="rr-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.engaged, t('tgt_engaged'))
                + chip(!!summary.retained, t('tgt_retained'))
                + chip(!!summary.equitable, t('tgt_equitable'))
                + chip(!!summary.aligned, t('tgt_aligned'))
                + chip(!!summary.onBudget, t('tgt_budget'));
            const metric = function (label, val) {
                return '<div class="rr-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const f1 = (typeof this._fmt1 === 'function') ? this._fmt1.bind(this) : function (v) { return v; };
            const metrics = ''
                + metric(t('kpi_engagement'), (summary.engagement != null ? summary.engagement : '-') + '/100')
                + metric(t('kpi_turnover'), (summary.turnover != null ? f1(summary.turnover) : '-') + '%')
                + metric(t('kpi_gap'), (summary.gap != null ? f1(summary.gap) : '-') + '%')
                + metric(t('kpi_fit'), (summary.fit != null ? summary.fit : '-') + '/100');
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="rr-cm">'
                +   '<div class="rr-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="rr-cm-verdict">' + verdict + '</div>'
                +   '<div class="rr-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="rr-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="rr-cm-targets">' + targets + '</div>'
                +   '<div class="rr-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="rr-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const engagement = Math.round(ds.engagement);
            const turnover = Math.round(ds.turnover * 10) / 10;
            const gap = Math.round(ds.gap * 10) / 10;
            const fit = Math.round(ds.fit);

            // Composite reward-reset score — balanced across the four board KPIs.
            // v1.1.0 FIX A - delegated to _composite(ds) so the persisted per-round score and this
            // completion composite are identical by construction (verbatim v1.0.0 formula incl. penalty).
            const composite = this._composite(ds);

            const engaged = engagement >= this.BENCHMARK_ENGAGEMENT - 4;
            const retained = turnover <= 13;
            const equitable = gap <= 2;
            const aligned = fit >= 70;
            const onBudget = !ds.overBudget;
            // A live perverse incentive (Common Error 3) and a starved development
            // line (Common Error 5 — "no growth path" is the #1 exit reason) are
            // disqualifying for a genuine reset, just like a broken envelope or a
            // misaligned metric set. They must block the top verdicts so wrong
            // strategies measurably underperform.
            const noPerverse = !ds.perverseLive;
            const fundedDev = ds.devSpend >= 1;
            const clean = noPerverse && fundedDev;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_lost`;
            if (engaged && retained && equitable && aligned && onBudget && clean && composite >= 78) perfKey = `grade_mastered`;
            else if (aligned && equitable && onBudget && clean && composite >= 62) perfKey = `grade_aligned`;
            else if (ds.overBudget) perfKey = `grade_envelope`;
            else if (ds.metricMisaligned) perfKey = `grade_metrics`;
            else if (!equitable) perfKey = `grade_inequity`;
            else if (ds.perverseLive) perfKey = `grade_perverse`;
            else if (!fundedDev) perfKey = `grade_devstarved`;
            else if (composite >= 50) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (engaged && retained && equitable && aligned && onBudget && clean) insights.push(window.mySimulation.t(`insight_mastered`));
            else if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            else if (ds.metricMisaligned) insights.push(window.mySimulation.t(`insight_metrics`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!equitable) insights.push(window.mySimulation.t(`insight_equity`));
            if (ds.perverseLive) insights.push(window.mySimulation.t(`insight_perverse`));
            if (ds.devSpend < 1) insights.push(window.mySimulation.t(`insight_nodev`));
            if (ds.noChangeMgmt) insights.push(window.mySimulation.t(`insight_changemgmt`));
            if (aligned && retained && engagement < this.BENCHMARK_ENGAGEMENT - 4) insights.push(window.mySimulation.t(`insight_engagement_lag`));

            return {
                gradeKey: perfKey,
                score: composite,
                engagement: engagement,
                turnover: turnover,
                gap: gap,
                fit: fit,
                engaged: engaged,
                retained: retained,
                equitable: equitable,
                aligned: aligned,
                onBudget: onBudget,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.metricMisaligned) return window.mySimulation.t(`hint_metrics`);
            if (ds.gap >= 8 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_equity`);
            if (ds.perverseLive) return window.mySimulation.t(`hint_perverse`);
            if (ds.devSpend < 1 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_nodev`);
            if (ds.turnover >= 18) return window.mySimulation.t(`hint_turnover`);
            if (ds.engagement >= this.BENCHMARK_ENGAGEMENT - 4 && ds.gap <= 2 && ds.fit >= 70) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
